import React, { useEffect, useRef, useState } from "react";
import { Layout } from "antd";
import styled, { keyframes } from "styled-components";
import "react-image-gallery/styles/css/image-gallery.css";
import "antd/dist/antd.css";
import Gallery from "../components/gallery";
import Greeting from "../components/greeting";
import Title from "../components/title";
import "../styles/index.css";
import GroovePaper from "../assets/GroovePaper.png";
import Location from "../components/location";
import Share from "../components/share";
import Quote from "../components/quote";
import Song from "../assets/song.mp3";
import HeartImg from "../assets/heart.png";
import AOS from "aos";
import "aos/dist/aos.css";

const { Footer } = Layout;

// 💫 애니메이션
const float = keyframes`
  0% { transform: translateY(0px); }
  50% { transform: translateY(-6px); }
  100% { transform: translateY(0px); }
`;

const romanticFadeOut = keyframes`
  0% { opacity: 1; transform: scale(1); }
  40% { transform: scale(1.1); }
  100% { opacity: 0; transform: scale(0.7); }
`;

const fadeIn = keyframes`
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
`;

const floatHearts = keyframes`
  0% { transform: translateY(0) scale(1); opacity: 0; }
  20% { opacity: 1; }
  100% { transform: translateY(-120vh) scale(1.4); opacity: 0; }
`;

// 🌸 초기 화면
const InitialScreen = styled.div`
  position: fixed;
  inset: 0;
  background: linear-gradient(180deg, #f9d9dd 0%, #fceef0 100%);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  z-index: 999;
  overflow: hidden;
  opacity: ${({ fadeOut }) => (fadeOut ? 0 : 1)};
  transition: opacity 1.5s ease;
  pointer-events: ${({ fadeOut }) => (fadeOut ? "none" : "auto")};
`;

// 💞 상단 이미지
const IntroImage = styled.img`
  width: 120px;
  height: auto;
  margin-bottom: 30px;
  opacity: 0.95;
  animation: ${float} 3s ease-in-out infinite;
  filter: drop-shadow(0 2px 4px rgba(0, 0, 0, 0.2));
`;

// 🎀 리본 버튼
const SoundButton = styled.button`
  position: relative;
  display: flex;
  justify-content: flex-end; /* 텍스트를 오른쪽으로 정렬 */
  align-items: center;
  background: linear-gradient(
    90deg,
    #f2d7b0 0% 30%,
    rgba(90, 60, 50, 0.9) 30% 100%
  );
  color: white;
  border: none;
  padding: 16px 48px;
  border-radius: 60px;
  font-size: 18px;
  font-weight: 600;
  letter-spacing: 0.6px;
  cursor: pointer;
  box-shadow: 0px 6px 14px rgba(0, 0, 0, 0.3);
  animation: ${float} 2.4s ease-in-out infinite;
  transition: all 0.4s ease;
  width: 260px; /* 약간 더 넓게 */
  height: 64px;
  backdrop-filter: blur(8px);
  overflow: hidden;

  span {
    position: relative;
    right: 10px;
    text-align: right;
    width: 60%;
  }

  /* 🎀 리본 라인 */
  &::before {
    content: "";
    position: absolute;
    left: 25%;
    top: 0;
    width: 3px;
    height: 100%;
    background: linear-gradient(
      180deg,
      #fff8f0 0%,
      #d8bca2 40%,
      #fff3e0 70%,
      #caa57d 100%
    );
    box-shadow: 0 0 6px rgba(255, 255, 255, 0.4);
    z-index: 2;
  }

  /* 🎗️ 리본 매듭 장식 */
  &::after {
    content: " ";
    position: absolute;
    left: 19%;
    top: 50%;
    transform: translateY(-50%) rotate(-5deg);
    font-size: 20px;
    z-index: 3;
    filter: drop-shadow(0 0 3px rgba(255, 255, 255, 0.6));
  }

  &:hover {
    transform: scale(1.05);
  }

  &:hover::before {
    box-shadow: 0 0 10px rgba(255, 220, 200, 0.9);
  }

  &.fade-out {
    animation: ${romanticFadeOut} 1s forwards;
  }
`;

// 💕 콘텐츠 래퍼
const Wrapper = styled.div`
  background: #efebe9;
  background-image: url(${GroovePaper});
  width: 100%;
  min-height: 100vh;
  opacity: ${({ isVisible }) => (isVisible ? 1 : 0)};
  animation: ${({ isVisible }) => (isVisible ? fadeIn : "none")} 1.8s ease;
  transition: opacity 1.5s ease;
`;

// 💖 하트 파티클
const HeartParticle = styled.span`
  position: absolute;
  bottom: -40px;
  color: ${({ color }) => color};
  font-size: ${({ size }) => size}px;
  left: ${({ left }) => left}%;
  animation: ${floatHearts} ${({ duration }) => duration}s linear infinite;
  animation-delay: ${({ delay }) => delay}s;
  opacity: 0.8;
  text-shadow: 0 0 10px ${({ color }) => color}88;
`;

const IndexPage = () => {
  const audioRef = useRef(null);
  const [showIntro, setShowIntro] = useState(true);
  const [fadeOutIntro, setFadeOutIntro] = useState(false);
  const [showContent, setShowContent] = useState(false);
  const [fadeButton, setFadeButton] = useState(false);
  const [hearts, setHearts] = useState([]);

  useEffect(() => {
    const script = document.createElement("script");
    script.async = true;
    script.src = "https://developers.kakao.com/sdk/js/kakao.min.js";
    document.body.appendChild(script);
    AOS.init({ duration: 1500 });

    // 🎨 랜덤 하트 생성
    const colors = ["#FFB6C1", "#FCE8D5", "#FF8FA3", "#FFD6DA", "#E57373"];
    const newHearts = Array.from({ length: 18 }).map(() => ({
      id: Math.random(),
      left: Math.random() * 100,
      size: 14 + Math.random() * 20,
      duration: 6 + Math.random() * 5,
      delay: Math.random() * 3,
      color: colors[Math.floor(Math.random() * colors.length)],
    }));
    setHearts(newHearts);

    return () => {
      document.body.removeChild(script);
    };
  }, []);

  const handleUnmute = () => {
    if (audioRef.current) {
      audioRef.current
        .play()
        .then(() => {
          setFadeButton(true);
          setTimeout(() => setFadeOutIntro(true), 600);
          setTimeout(() => {
            setShowIntro(false);
            setShowContent(true);
          }, 1800);
        })
        .catch((e) => console.log("재생 불가:", e));
    }
  };

  return (
    <>
      {/* 🌸 인트로 */}
      {showIntro && (
        <InitialScreen fadeOut={fadeOutIntro}>
          {hearts.map((h) => (
            <HeartParticle
              key={h.id}
              left={h.left}
              size={h.size}
              duration={h.duration}
              delay={h.delay}
              color={h.color}
            >
              ♥
            </HeartParticle>
          ))}

          <IntroImage src={HeartImg} alt="intro heart" />
          <SoundButton
            className={fadeButton ? "fade-out" : ""}
            onClick={handleUnmute}
          >
            <span>Dear My Love 💌</span>
          </SoundButton>
        </InitialScreen>
      )}

      {/* 🎵 음악 */}
      <audio ref={audioRef} loop playsInline>
        <source src={Song} type="audio/mp3" />
      </audio>

      {/* 💌 메인 콘텐츠 */}
      <Wrapper isVisible={showContent}>
        <Title />
        <Greeting />
        <Location />
        <Quote />
        <Gallery />
        <Share />
        <Footer
          style={{
            background: "#D7CCC8",
            backgroundImage: `url(${GroovePaper})`,
            opacity: 0.6,
            textAlign: "center",
            padding: "20px",
          }}
        >
          Copyright © 2025 EO JAESUNG
        </Footer>
      </Wrapper>
    </>
  );
};

export default IndexPage;